# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HÜCRENİN ÜÇ TEMEL KISMI: DIŞTAN İÇE DOĞRU YAPI (FB.5.3.1)</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Hücre Zarı (Dış Katman)</text>\n  <text x="125" y="100" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Hücreyi dış ortamdan ayırır</text>\n  <text x="125" y="120" text-anchor="middle" font-size="11.5" fill="#1e3a8a">ve hücreye şekil verir.</text>\n  <text x="125" y="146" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Canlı, esnek ve ince yapılıdır.</text>\n  <text x="125" y="172" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Seçici geçirgendir (madde</text>\n  <text x="125" y="192" text-anchor="middle" font-size="11.5" fill="#1e3a8a">giriş çıkışını denetler).</text>\n  <text x="125" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Bitki duvarı ise cansız ve tam geçirgendir.</text>\n\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">2. Sitoplazma (Orta Kısım)</text>\n  <text x="350" y="100" text-anchor="middle" font-size="11.5" fill="#78350f">• Hücre zarı ile çekirdek arasını</text>\n  <text x="350" y="120" text-anchor="middle" font-size="11.5" fill="#78350f">dolduran yarı akışkan sıvıdır.</text>\n  <text x="350" y="146" text-anchor="middle" font-size="11.5" fill="#78350f">• Büyük kısmı sudan oluşur,</text>\n  <text x="350" y="166" text-anchor="middle" font-size="11.5" fill="#78350f">yumurta akı kıvamındadır.</text>\n  <text x="350" y="192" text-anchor="middle" font-size="11.5" fill="#78350f">• Yaşamsal olayları yürüten</text>\n  <text x="350" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">organeller sitoplazmada yer alır.</text>\n\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#fdf2f8" stroke="#db2777" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">3. Çekirdek (Merkez)</text>\n  <text x="575" y="100" text-anchor="middle" font-size="11.5" fill="#831843">• Hücrenin yönetim ve denetim</text>\n  <text x="575" y="120" text-anchor="middle" font-size="11.5" fill="#831843">merkezidir (beyni gibidir).</text>\n  <text x="575" y="146" text-anchor="middle" font-size="11.5" fill="#831843">• Büyüme, gelişme, solunum ve</text>\n  <text x="575" y="166" text-anchor="middle" font-size="11.5" fill="#831843">bölünme olaylarını yönetir.</text>\n  <text x="575" y="192" text-anchor="middle" font-size="11.5" fill="#831843">• Kalıtsal özellikleri taşıyan</text>\n  <text x="575" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#be185d">yapılar çekirdekte bulunur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SİTOPLAZMADAKİ ORGANELLER VE GÖREVLERİ</text>\n  <rect x="20" y="44" width="320" height="96" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="180" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">• Mitokondri (Enerji Santrali) &amp; Ribozom</text>\n  <text x="180" y="88" text-anchor="middle" font-size="11.5" fill="#14532d">Mitokondri: Besin ve oksijenden enerji üretir.</text>\n  <text x="180" y="110" text-anchor="middle" font-size="11.5" fill="#14532d">Ribozom: Tüm hücrelerde protein sentezler (en küçük).</text>\n  <text x="180" y="130" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Her ikisi de hem bitki hem hayvan hücresinde ortaktır.</text>\n\n  <rect x="360" y="44" width="320" height="96" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.5"/>\n  <text x="520" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">• Endoplazmik Retikulum, Golgi ve Koful</text>\n  <text x="520" y="88" text-anchor="middle" font-size="11.5" fill="#1e3a8a">E. Retikulum: Madde iletim kanalları · Golgi: Salgı/paketleme</text>\n  <text x="520" y="110" text-anchor="middle" font-size="11.5" fill="#1e3a8a">Koful: Besin, su ve atık depolayan keseciklerdir.</text>\n  <text x="520" y="130" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Koful bitkide büyük ve az; hayvanda küçük ve çoktur.</text>\n\n  <rect x="20" y="152" width="320" height="92" rx="8" fill="#dcfce7" stroke="#15803d" stroke-width="1.5"/>\n  <text x="180" y="174" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#14532d">• Kloroplast (Bitki Hücresine Özgü)</text>\n  <text x="180" y="198" text-anchor="middle" font-size="11.5" fill="#166534">Bitkiye yeşil renk verir; güneş ışığıyla fotosentez</text>\n  <text x="180" y="218" text-anchor="middle" font-size="11.5" fill="#166534">yaparak besin ve oksijen üretir (hayvanda yoktur).</text>\n\n  <rect x="360" y="152" width="320" height="92" rx="8" fill="#fce7f3" stroke="#be185d" stroke-width="1.5"/>\n  <text x="520" y="174" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9d174d">• Sentrozom ve Lizozom (Hayvan Hücresinde)</text>\n  <text x="520" y="198" text-anchor="middle" font-size="11.5" fill="#831843">Sentrozom: Hayvan hücresinde hücre bölünmesinde görevlidir.</text>\n  <text x="520" y="218" text-anchor="middle" font-size="11.5" fill="#831843">Lizozom: Hücre içi sindirim yapar (gelişmiş bitkide bulunmaz).</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">BİTKİ VE HAYVAN HÜCRESİ KARŞILAŞTIRMASI (FB.5.3.1)</text>\n  <rect x="20" y="48" width="210" height="192" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Bitki Hücresi Özellikleri</text>\n  <text x="125" y="98" text-anchor="middle" font-size="11.5" fill="#14532d">• Şekli köşelidir (dikdörtgenimsi).</text>\n  <text x="125" y="122" text-anchor="middle" font-size="11.5" fill="#14532d">• Hücre duvarı (çeperi) VARDIR.</text>\n  <text x="125" y="146" text-anchor="middle" font-size="11.5" fill="#14532d">• Kloroplast organeli VARDIR.</text>\n  <text x="125" y="170" text-anchor="middle" font-size="11.5" fill="#14532d">• Sentrozom organeli YOKTUR.</text>\n  <text x="125" y="194" text-anchor="middle" font-size="11.5" fill="#14532d">• Kofulları BÜYÜK ve AZ sayıdadır.</text>\n  <text x="125" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Örnek: Soğan zarı, yaprak hücresi</text>\n\n  <rect x="245" y="48" width="210" height="192" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Ortak Yapı ve Organeller</text>\n  <text x="350" y="98" text-anchor="middle" font-size="11.5" fill="#78350f">• Hücre zarı, Sitoplazma, Çekirdek</text>\n  <text x="350" y="122" text-anchor="middle" font-size="11.5" fill="#78350f">• Mitokondri (Enerji üretimi)</text>\n  <text x="350" y="146" text-anchor="middle" font-size="11.5" fill="#78350f">• Ribozom (Protein üretimi)</text>\n  <text x="350" y="170" text-anchor="middle" font-size="11.5" fill="#78350f">• Endoplazmik Retikulum (İletim)</text>\n  <text x="350" y="194" text-anchor="middle" font-size="11.5" fill="#78350f">• Golgi Cisimciği (Salgı) ve Koful</text>\n  <text x="350" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">Yaşamsal faaliyetler ortak yürütülür.</text>\n\n  <rect x="470" y="48" width="210" height="192" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Hayvan Hücresi Özellikleri</text>\n  <text x="575" y="98" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Şekli yuvarlak / ovaldir.</text>\n  <text x="575" y="122" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Hücre duvarı (çeperi) YOKTUR.</text>\n  <text x="575" y="146" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Kloroplast organeli YOKTUR.</text>\n  <text x="575" y="170" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Sentrozom ve Lizozom VARDIR.</text>\n  <text x="575" y="194" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Kofulları KÜÇÜK ve ÇOK sayıdadır.</text>\n  <text x="575" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Örnek: Ağız içi epitel, kas hücresi</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
